import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_each_session_once():
    groups = {
        "large": [{"converted": True}, {"converted": False}, {"converted": False}],
        "small": [{"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window():
    assert conversions_in_window([1, 2, 3, 4], 2) == 7
    assert conversions_in_window([1, 2], 0) == 0
    assert conversions_in_window([1, 2], 5) == 3


def test_parse_session_log_values_whitespace_and_skipped_lines():
    assert parse_session_log([
        "  # comment",
        "   ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


def test_parse_session_log_errors_report_original_line_number():
    with pytest.raises(ValueError, match="line 3"):
        parse_session_log(["# comment", "", "x1,nope,1"])
    with pytest.raises(ValueError, match="line 1"):
        parse_session_log(["x1,2"])


def test_dedupe_sessions_keeps_last_duplicate_id():
    events = [
        {"id": "x", "day": 1, "converted": True},
        {"id": "y", "day": 2, "converted": False},
        {"id": "x", "day": 3, "converted": False},
    ]
    assert dedupe_sessions(events) == [
        {"id": "y", "day": 2, "converted": False},
        {"id": "x", "day": 3, "converted": False},
    ]


def test_dedupe_sessions_sorts_by_day_then_id():
    events = [
        {"id": "z", "day": 2, "converted": False},
        {"id": "b", "day": 1, "converted": True},
        {"id": "a", "day": 1, "converted": False},
    ]
    assert [event["id"] for event in dedupe_sessions(events)] == ["a", "b", "z"]


def test_daily_conversion_counts_inclusive_range():
    events = [
        {"id": "early", "day": 0, "converted": True},
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 1, "converted": False},
        {"id": "c", "day": 3, "converted": True},
        {"id": "late", "day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [1, 0, 1]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary():
    groups = {
        "a": [{"id": "1", "day": 1, "converted": True}],
        "b": [
            {"id": "2", "day": 2, "converted": False},
            {"id": "3", "day": 3, "converted": True},
        ],
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "a": [{"converted": True}],
        "b": [{"converted": False}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    assert conversion_rate_by_group({"z": [], "a": [{"converted": True}]}) == {
        "a": 1.0,
        "z": None,
    }


def test_longest_conversion_streak():
    assert longest_conversion_streak([1, 0, 2, 3, 0]) == 2
    assert longest_conversion_streak([]) == 0

